        vst41.u32 {data0, data1, data2, data3}, [in]
        vst42.u32 {data0, data1, data2, data3}, [in]
        vst43.u32 {data0, data1, data2, data3}, [in]!
        le lr, haetae_layer78_loop

        vpop {d8-d15}
        pop {r4-r12, lr}
        bx lr
.size haetae_ntt_asm_paired_slothy, .-haetae_ntt_asm_paired_slothy
